css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .half { position: absolute; left: 32%; top: 30%; width: 36%; height: 40%; background: linear-gradient(var(--accent-2), var(--accent)); }
.loader .half:nth-of-type(1) { border-radius: 100% 0 0 100% / 50% 0 0 50%; transform-origin: 100% 50%; animation: pod-open-left calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .half:nth-of-type(2) { border-radius: 0 100% 100% 0 / 0 50% 50% 0; transform-origin: 0 50%; animation: pod-open-right calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader i { position: absolute; left: 46%; top: 46%; width: 8%; height: 8%; border-radius: 50% 50% 50% 0; background: var(--accent-2); opacity: 0; animation: pod-seed calc(var(--loader-speed) * 2.4) cubic-bezier(.2, .7, .4, 1) infinite; }
.loader i:nth-of-type(1) { --dx: -230%; --dy: -180%; }
.loader i:nth-of-type(2) { --dx: 240%; --dy: -170%; }
.loader i:nth-of-type(3) { --dx: -190%; --dy: 210%; }
.loader i:nth-of-type(4) { --dx: 220%; --dy: 200%; }
@keyframes pod-open-left { 0%, 30% { transform: rotate(0deg); } 55%, 78% { transform: rotate(-58deg); } 100% { transform: rotate(0deg); } }
@keyframes pod-open-right { 0%, 30% { transform: rotate(0deg); } 55%, 78% { transform: rotate(58deg); } 100% { transform: rotate(0deg); } }
@keyframes pod-seed { 0%, 38% { opacity: 0; transform: translate(0, 0) scale(.4); } 48% { opacity: 1; transform: translate(0, 0) scale(1); } 88%, 100% { opacity: 0; transform: translate(var(--dx, 0%), var(--dy, 0%)) scale(.6); } }
